def run(v):
    import json, datetime
    ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    NAMES = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
    UNITS = dict(TL=('Türk Lirası', 'kuruş'), USD=('Dolar', 'sent'), EUR=('Euro', 'sent'), GBP=('İngiliz Sterlini', 'peni'))
    VMAP = dict(a='ı', e='i', i='i', o='u', u='u')
    VMAP['ı'] = 'ı'
    VMAP['ö'] = 'ü'
    VMAP['ü'] = 'ü'
    APO = chr(39)
    def w3(n):
        h, r = divmod(n, 100)
        t, o = divmod(r, 10)
        p = []
        if h:
            p.append('yüz' if h == 1 else ONES[h] + ' yüz')
        if t:
            p.append(TENS[t])
        if o:
            p.append(ONES[o])
        return ' '.join(p)
    def words(n):
        n = int(n)
        if n == 0:
            return 'sıfır'
        parts = []
        for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
            q, n = divmod(n, val)
            if q:
                parts.append('bin' if (val == 1000 and q == 1) else w3(q) + ' ' + nm)
        if n:
            parts.append(w3(n))
        return ' '.join(parts)
    def amt(x, cur):
        c = int(round(abs(float(x)) * 100))
        m, s = divmod(c, 100)
        u, su = UNITS[cur]
        if m == 0 and s:
            return words(s) + ' ' + su
        t = words(m) + ' ' + u
        if s:
            t = t + ' ' + words(s) + ' ' + su
        return t
    def cop(text):
        ws = text.split()
        if not ws:
            return text
        w = ws[-1]
        if w == 'Euro':
            return text + APO + 'dur'
        ref = words(int(w)).split()[-1] if w.isdigit() else w
        last = ''
        for ch in reversed(ref.lower()):
            if ch in VMAP:
                last = ch
                break
        d = 't' if ref[-1] in 'çfhkpsşt' else 'd'
        apo = APO if (w[0].isupper() or w[0].isdigit()) else ''
        return text + apo + d + VMAP.get(last, 'i') + 'r'
    def pd(s):
        try:
            p = str(s).strip().split('.')
            return datetime.date(int(p[2]), int(p[1]), int(p[0]))
        except Exception:
            return None
    def sd(d):
        return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
    def num(blk, k):
        try:
            return float(blk.get(k) or 0)
        except Exception:
            return 0.0
    def nodebt(lst):
        if not lst:
            return ''
        s = lst[0] if len(lst) == 1 else ', '.join(lst[:-1]) + ' ve ' + lst[-1]
        return s + ' borcunuz bulunmamaktadır.'
    def loadj(x, dflt):
        if isinstance(x, (list, dict)):
            return x
        try:
            return json.loads(str(x))
        except Exception:
            return dflt
    b = loadj(v.get('bal_compact'), dict())
    if not isinstance(b, dict) or not b:
        v['reading_route'] = 'error'
        return
    cards = loadj(v.get('cards_json'), [])
    if not isinstance(cards, list):
        cards = []
    cards = [c for c in cards if isinstance(c, dict)]
    elig = [c for c in cards if c.get('m')]
    try:
        today = datetime.date.fromisoformat(str(v.get('now') or '')[:10])
    except Exception:
        today = None
    l4 = str(b.get('cardNumberLast4') or '')
    if str(v.get('cards_state')) == 'one':
        idx = str(v.get('sel_card_index') or '')
    else:
        idx = str(v.get('cards_balance_args.card_index') or '').strip()
        try:
            idx = str(int(float(idx)))
        except Exception:
            pass
    sel = None
    for c in cards:
        if str(c.get('i')) == idx and (not l4 or str(c.get('l4')) == l4):
            sel = c
    if sel is None:
        bn = str(b.get('cardNumber') or '')
        for c in cards:
            if l4 and str(c.get('l4')) == l4 and str(c.get('n') or '')[:4] == bn[:4]:
                sel = c
                break
    if sel is None:
        v['reading_route'] = 'error'
        return
    v['sel_card_number'] = str(sel.get('n') or '')
    v['sel_card_index'] = str(sel.get('i'))
    name = str(sel.get('p') or b.get('productName') or '').strip()
    l4 = l4 or str(sel.get('l4') or '')
    l4s = ' '.join(DIG[int(ch)] for ch in l4 if ch.isdigit())
    base = 'Sonu ' + l4s + ' ile biten ' + (name + ' ' if name else '')
    card_ref = base + 'kartınızın'
    v['card_ref'] = card_ref
    st = pd(b.get('statementDate'))
    due = pd(b.get('lastPayDate'))
    nst = pd(b.get('nextStatementDate'))
    v['stmt_date'] = str(b.get('statementDate') or '') if st else 'yok'
    v['has_statement'] = 'yes' if st else 'no'
    blocks = []
    for key, cur in (('debtTL', 'TL'), ('debtUSD', 'USD'), ('debtEUR', 'EUR'), ('debtGBP', 'GBP')):
        blk = b.get(key)
        if isinstance(blk, dict) and len(blk) > 0:
            blocks.append((cur, blk))
    tl = None
    for cur, blk in blocks:
        if cur == 'TL':
            tl = blk
    def totals(prefix):
        out = []
        clear = []
        for cur, blk in blocks:
            t = num(blk, 'totalDebt')
            if t > 0:
                lead = (prefix + 'toplam ') if (prefix and not out) else 'Toplam '
                out.append(lead + NAMES[cur] + ' borcunuz ' + cop(amt(t, cur)) + '.')
            else:
                clear.append(NAMES[cur])
        if out and clear:
            out.append(nodebt(clear))
        return out
    kind = 'debt'
    parts = []
    if st is None:
        kind = 'nodebt'
        parts.append(card_ref + ' henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
        if nst is not None:
            parts.append('İlk hesap kesim tarihiniz ' + sd(nst) + ' olacak.')
    elif today is not None and (today == st or today == nst):
        parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        tt = totals(base + 'kartınıza ait ')
        parts.extend(tt if tt else [card_ref + ' toplam borcu bulunmamaktadır.'])
    elif str(b.get('statementPaymentStatus') or '').upper() == 'NO_DEBT' or not any(num(blk, 'remainingDebt') > 0 for cur, blk in blocks):
        kind = 'nodebt'
        parts.append(card_ref + ' ' + sd(st) + ' tarihli ekstresinden borcunuz bulunmamaktadır.')
        if tl is not None and num(tl, 'totalDebt') > 0:
            parts.append('Gelecek dönemler dahil toplam borcunuz ' + cop(amt(num(tl, 'totalDebt'), 'TL')) + '.')
        if due is not None:
            parts.append('Son ödeme tarihiniz ' + sd(due) + ' olacaktır.')
    elif today is not None and due is not None and today > due:
        parts.append(card_ref + ' son ödeme tarihi olan ' + sd(due) + ' geçti.')
        tt = totals('')
        parts.extend(tt if tt else ['Kartınızın toplam borcu bulunmamaktadır.'])
        if str(b.get('automaticPaymentFlag') or '').upper() == 'Y' and tl is not None and num(tl, 'remainAutomaticPaymentAmount') > 0:
            parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + cop(amt(num(tl, 'remainAutomaticPaymentAmount'), 'TL')) + '.')
    else:
        prefix = base + 'kartınıza ait ' + sd(st) + ' tarihinde kesilen ekstre '
        lines = []
        clear = []
        for cur, blk in blocks:
            sdb = num(blk, 'statementDebt')
            mn = num(blk, 'minPayment')
            rd = num(blk, 'remainingDebt')
            rm = num(blk, 'remainingMinPayment')
            if rd <= 0:
                clear.append(NAMES[cur])
                continue
            if cur == 'TL':
                if rm > 0 and rm >= mn:
                    s = 'Türk Lirası borcunuz ' + amt(sdb, cur) + ', ödenmesi gereken minimum tutar ' + cop(amt(mn, cur)) + '.'
                elif rm <= 0:
                    s = 'Türk Lirası borcunuz ' + amt(sdb, cur) + ', kalan toplam borcunuz ' + cop(amt(rd, cur)) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                else:
                    s = 'Türk Lirası borcunuz ' + amt(sdb, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', kalan minimum ödeme tutarınız ' + cop(amt(rm, cur)) + '.'
            else:
                s = NAMES[cur] + ' borcunuz ' + amt(sdb, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', ödenmesi gereken minimum tutar ' + cop(amt(mn, cur)) + '.'
            lines.append(prefix + s if not lines else s)
        parts.extend(lines)
        if clear:
            parts.append(nodebt(clear))
        if due is not None and today is not None and due == today:
            parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
        elif due is not None:
            parts.append('Borçlarınız için son ödeme tarihiniz ' + cop(sd(due)) + '.')
    read = [x for x in str(v.get('read_cards') or '').split(',') if x]
    if str(sel.get('i')) not in read:
        read.append(str(sel.get('i')))
    v['read_cards'] = ','.join(read)
    left = [c for c in elig if str(c.get('i')) not in read]
    more = len(elig) > 1 and len(left) > 0
    v['has_other_cards'] = 'yes' if more else 'no'
    if str(v.get('email_state')) == 'ok':
        offer = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        offer = 'Hesap kesim tarihinizi değiştirebilirim.'
    q = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    text = ' '.join(p for p in parts if p)
    if kind == 'nodebt':
        v['offer_text'] = ''
        if more:
            v['reading_text'] = text + ' ' + q
            v['reading_route'] = 'main'
        else:
            v['reading_text'] = text + ' Sizi ana menüye yönlendiriyorum.'
            v['reading_route'] = 'nodebt_end'
    else:
        v['offer_text'] = offer
        v['reading_text'] = text + ' ' + (q if more else offer)
        v['reading_route'] = 'main'
try:
    run(vars)
except Exception:
    vars['reading_route'] = 'error'
